import (
	context "context"
	fernclient "github.com/openapi-per-spec-base-path-disabled/fern/client"
	option "github.com/openapi-per-spec-base-path-disabled/fern/option"
)

client := fernclient.NewClient(
	option.WithClientCredentials(
		"<YOUR_CLIENT_ID>",
		"<YOUR_CLIENT_SECRET>",
	),
)
response, err := client.ListItems(
	context.TODO(),
)

import (
	context "context"
	fernclient "github.com/openapi-per-spec-base-path-disabled/fern/client"
	oauth "github.com/openapi-per-spec-base-path-disabled/fern/oauth"
	option "github.com/openapi-per-spec-base-path-disabled/fern/option"
)

client := fernclient.NewClient(
	option.WithClientCredentials(
		"<YOUR_CLIENT_ID>",
		"<YOUR_CLIENT_SECRET>",
	),
)
response, err := client.Oauth.GetToken(
	context.TODO(),
	&oauth.GetTokenRequest{
		ClientID:     "client_id",
		ClientSecret: "client_secret",
	},
)
